:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #7a8ba8;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: repeating-linear-gradient(0deg, transparent, transparent 15px, rgba(255,255,255,0.02) 15px, rgba(255,255,255,0.02) 16px);
  font-family: 'Courier New', monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 28px 24px;
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}
h1 {
  margin: 0 0 4px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}
.formula {
  margin: 0 0 8px;
  font-size: 0.8rem;
  color: var(--muted);
  line-height: 1.5;
}
label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}
input, select, button {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px;
  border: 3px solid var(--muted);
  border-radius: 0;
  background: var(--bg);
  color: var(--text);
  outline: none;
  transition: border-color 0.1s, background 0.1s;
}
input:focus, select:focus, button:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}
input:hover, select:hover { border-color: var(--text); }
button {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
  cursor: pointer;
  margin-top: 4px;
}
button:hover { background: #f05a72; border-color: #f05a72; }
button:active { transform: translate(2px, 2px); box-shadow: none; }
.output-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 3px dashed var(--muted);
  padding: 12px 16px;
  margin-top: 8px;
}
.output-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}
#result {
  font-size: 1.6rem;
  font-weight: bold;
  color: var(--accent);
  min-width: 80px;
  text-align: right;
}
@media (max-width: 400px) {
  .card { padding: 20px 16px; }
  h1 { font-size: 1.2rem; }
  .formula { font-size: 0.7rem; }
}

const tempInput = document.getElementById('temperature');
const direction = document.getElementById('direction');
const convertBtn = document.getElementById('convert');
const resultEl = document.getElementById('result');

function convert() {
  const raw = tempInput.value.trim();
  if (raw === '') {
    resultEl.textContent = 'Error';
    return;
  }
  const x = Number(raw);
  if (!Number.isFinite(x)) {
    resultEl.textContent = 'Error';
    return;
  }
  let out;
  if (direction.value === 'c-to-f') {
    out = x * 9 / 5 + 32;
  } else {
    out = (x - 32) * 5 / 9;
  }
  resultEl.textContent = out.toFixed(2);
}

convertBtn.addEventListener('click', convert);
tempInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') convert();
});
